paginas.codigo:
.productos {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
}

.tarjeta {
  width: 140px;
}

.buscador {
  display: flex;
  gap: 8px;
}

.buscador input {
  flex: 1;        /* ocupa lo que sobra */
}

.buscador button {
  flex: none;     /* 0 0 auto: tamaño fijo */
}

.cabecera {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.cabecera nav {
  display: flex;
  gap: 16px;
}
